import{z as B,x as A,o as t,c as d,q as o,j as i,D as s,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MOESI 与 MESIF","description":"","frontmatter":{"title":"MOESI 与 MESIF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/moesi-mesif.md","filePath":"cs/moesi-mesif.md","lastUpdated":1791413859000}'),p={name:"cs/moesi-mesif.md"};function S(m,a,c,M,h,F){const r=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="moesi-与-mesif" tabindex="-1">MOESI 与 MESIF <a class="header-anchor" href="#moesi-与-mesif" aria-label="Permalink to &quot;MOESI 与 MESIF&quot;">​</a></h1><div class="epigraph"><p>脏数据不必先写回 LLC 再给请求者：Owned 允许共享脏副本并指定一个责任人；Forward 指定谁来响应共享读，避免所有 S 一起抢答。</p><footer>—— 据 Sweazey and Smith；AMD64 对 MOESI 的描述；Intel 对 MESIF 的描述 整理</footer></div><p><a href="/cs/hugepage-tlb-reach">上一课</a> 放大单核翻译。多核上 <a href="/cs/mesi-protocol">MESI</a> 已经保证至多一份 M。脏行被他核读时，MESI 通常写回再双方变 S——LLC 与内存带宽被打满。本课不重画四态。缺口是<strong>O（Owned）与 F（Forward）：共享时仍能指出数据从哪来、脏责任在谁。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核 A 持有 M，核 B 读同一行：数据在 A 的 L1 里最新。若必须先写到 LLC，延迟和功耗都高。MOESI 加 Owned：脏且可共享，O 核负责将来写回，其他核为 S。MESIF 加 Forward：干净共享时指定一个 F 核响应后续读，避免监听风暴里所有 S 重复提供。缺口不是分区，而是<strong>五态机减少写回与重复响应。</strong></p><p><span class="marginnote">MOESI 常见于 AMD 窥探/Infinity。MESIF 用于 Intel QPI/UPI：F 是干净共享的指定转发者。二者都不是内存模型，只是副本放置。</span></p><p><span class="marginnote">术语翻译：「窥探」就是每个核的缓存都监听总线上别人发的读写请求，看到涉及自己持有的行就主动应答或让出——像合租室友都竖着耳朵听敲门声，谁保管钥匙谁去开门。</span></p><p><span class="marginnote">常见误区：初学者容易以为 O 和 F 是「新的一致性规则」或更强的保证。其实行里的数据没变，变的只是「谁来应答、谁负责写回」这份责任分工；可写副本至多一份的不变式与 MESI 完全相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MOESI：M 被他核读 → 提供者变 O，请求者变 S，数据直接 cache-to-cache，内存可暂不更新。O 被写或替换则写回。MESIF：S 集合里指定 F；后续共享读由 F 提供，其余 S 沉默。</p>',10)),(t(),i(n,null,{default:s(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22M%20%E8%84%8F%E7%8B%AC%E6%9C%89%22%5D%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20O%5B%22O%20%E8%84%8F%E5%85%B1%E4%BA%AB%E8%B4%A3%E4%BB%BB%E4%BA%BA%22%5D%0A%20%20O%20--%3E%20S%5B%22%E5%85%B6%E4%BB%96%E6%A0%B8%20S%22%5D%0A%20%20S2%5B%22%E5%B9%B2%E5%87%80%E5%85%B1%E4%BA%AB%22%5D%20--%3E%20F%5B%22F%20%E6%8C%87%E5%AE%9A%E8%BD%AC%E5%8F%91%22%5D%0A%20%20F%20--%3E%7C%22%E4%BB%96%E6%A0%B8%E8%AF%BB%22%7C%20F%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("不变式仍是：可写副本至多一份（M 或即将升级者）；脏至多一份责任人（M 或 O）。"),e("a",{href:"/cs/retire-precise-exception"},"退休"),E(" 的 store 仍只有提交后才进入这些状态。cache-to-cache 把 "),e("a",{href:"/cs/mlp-memory-parallelism"},"MLP"),E(" 的 miss 延迟从 DRAM 变成核间互联，后课 socket 互连会再放大这段。")],-1)),a[5]||(a[5]=e("p",null,"伪共享不因 O/F 消失：行粒度还在，只是颠簸走核间而不是 DRAM。",-1)),a[6]||(a[6]=e("p",null,"同一件事（核 B 读核 A 手里的脏行）在两种协议下走的路不同：",-1)),(t(),i(n,null,{default:s(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E6%A0%B8%20B%20%E8%AF%BB%E6%A0%B8%20A%20%E6%8C%81%E6%9C%89%E7%9A%84%E8%84%8F%E8%A1%8C%22%5D%20--%3E%20Q%7B%22%E6%8C%89%E5%93%AA%E5%A5%97%E5%8D%8F%E8%AE%AE%3F%22%7D%0A%20%20Q%20--%20%22MESI%22%20--%3E%20WB%5B%22A%20%E5%85%88%E5%86%99%E5%9B%9E%20LLC%20%E4%B8%8E%E5%86%85%E5%AD%98%22%5D%0A%20%20WB%20--%3E%20BOTH%5B%22%E5%8F%8C%E6%96%B9%E5%8F%98%20S%2C%20B%20%E4%BB%8E%E5%86%85%E5%AD%98%E4%BE%A7%E5%8F%96%22%5D%0A%20%20Q%20--%20%22MOESI%22%20--%3E%20CT%5B%22cache-to-cache%20%E7%9B%B4%E6%8E%A5%E4%BC%A0%22%5D%0A%20%20CT%20--%3E%20OW%5B%22A%20%E5%8F%98%20O%20%E8%B4%9F%E8%B4%A3%E5%B0%86%E6%9D%A5%E5%86%99%E5%9B%9E%2C%20B%20%E5%8F%98%20S%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：从隔壁核的缓存拿一行数据走核间互联约几十纳秒；先写回 DRAM 再读回来则要上百纳秒。共享热点数据时，cache-to-cache 这条近路能把读延迟砍掉一半以上，还省一次内存带宽。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把目录里的「owner 指针」写完，下一课目录扩展性会把窥探广播换掉。也不把 ARM 的 MOESI 变体逐比特对照。原子操作如何在这些态上锁 cache 行，是后课。</p><p>后课默认：共享脏可以不立即写内存；指定转发者减少重复应答。核数再涨，广播监听本身不可扩展。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MOESI 的 O 允许共享脏；MESIF 的 F 指定干净共享的响应者。</li><li>协议管副本，不管多地址顺序。</li><li>目录如何避免广播，是下一课扩展性。</li><li>出处：Sweazey and Smith；AMD MOESI；Intel MESIF。</li></ul>',6))])}const O=B(p,[["render",S]]);export{f as __pageData,O as default};
